package com.lordescanor.botforge;
import android.os.*;import android.view.*;import android.widget.*;import android.content.*;import android.net.Uri;import androidx.core.content.FileProvider;import org.json.*;import java.io.File;
public class BotsFragment extends androidx.fragment.app.Fragment{
 public View onCreateView(android.view.LayoutInflater i,ViewGroup p,Bundle b){View v=i.inflate(R.layout.fragment_bots,p,false);LinearLayout box=v.findViewById(R.id.list);JSONArray a=new BotStore(getActivity()).all();if(a.length()==0){TextView t=new TextView(getActivity());t.setText("لا توجد بوتات منشأة بعد");t.setTextColor(0xff9AA5B1);t.setTextSize(16);box.addView(t);}else try{for(int x=0;x<a.length();x++){JSONObject o=a.getJSONObject(x);LinearLayout row=new LinearLayout(getActivity());row.setOrientation(LinearLayout.VERTICAL);row.setPadding(18,18,18,18);row.setBackgroundResource(R.drawable.bg_card);TextView t=new TextView(getActivity());t.setText("🤖 "+o.optString("name")+"\n📱 "+o.optString("number"));t.setTextColor(0xffF4F5F7);t.setTextSize(16);row.addView(t);Button share=new Button(getActivity());share.setText("مشاركة / حفظ ZIP");share.setOnClickListener(z->{try{File file=new File(o.optString("zip"));Uri u=FileProvider.getUriForFile(getActivity(),getActivity().getPackageName()+".fileprovider",file);Intent s=new Intent(Intent.ACTION_SEND);s.setType("application/zip");s.putExtra(Intent.EXTRA_STREAM,u);s.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(s,"حفظ أو إرسال البوت"));}catch(Exception e){Toast.makeText(getActivity(),"ملف ZIP غير موجود",Toast.LENGTH_LONG).show();}});row.addView(share);box.addView(row);Space sp=new Space(getActivity());box.addView(sp,new LinearLayout.LayoutParams(1,10));}}catch(Exception ignored){}return v;}
}
